import{_ as d,o,c as a,a2 as t}from"./chunks/framework.DoCD98hS.js";const u=JSON.parse('{"title":"tpl-vue2-admin-ele-vea 独立改造说明","description":"","frontmatter":{},"headers":[],"relativePath":"guide/vea-standalone.md","filePath":"guide/vea-standalone.md","lastUpdated":null}'),c={name:"guide/vea-standalone.md"};function l(n,e,s,i,r,p){return o(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="tpl-vue2-admin-ele-vea-独立改造说明" tabindex="-1">tpl-vue2-admin-ele-vea 独立改造说明 <a class="header-anchor" href="#tpl-vue2-admin-ele-vea-独立改造说明" aria-label="Permalink to &quot;tpl-vue2-admin-ele-vea 独立改造说明&quot;">​</a></h1><p>记录 <code>@melt-js/tpl-vue2-admin-ele-vea</code> 脱离 monorepo <code>workspace:*</code>、在仓库外独立安装运行的一次改造。当前是 <strong>vendor 兜底的临时态</strong>：提供方 <code>comps-vue2-ele-vea</code> 尚未发布到 npm，其远程产物与代理入口临时放在消费方副本内；该包发版后需按文末步骤回归标准 <code>node_modules</code> 链路。</p><div class="info custom-block"><p class="custom-block-title">状态边界</p><p>本文记录的是副本 dev 冒烟与源码审计结果，不代表 npm 已发布版本；生产构建、线上托管验收见文末待补项。</p></div><h2 id="改造前依赖状态" tabindex="-1">改造前依赖状态 <a class="header-anchor" href="#改造前依赖状态" aria-label="Permalink to &quot;改造前依赖状态&quot;">​</a></h2><p>模板直接依赖三个内部包，对照 npm 官方源 latest：</p><table tabindex="0"><thead><tr><th>内部包</th><th>副本依赖版本</th><th>npm 状态</th><th>处理方式</th></tr></thead><tbody><tr><td><code>@melt-js/comps-vue2</code></td><td><code>2026.11.17</code></td><td>已发布</td><td>走 npm 实发版本</td></tr><tr><td><code>@melt-js/comps-vue2-ele</code></td><td><code>2026.11.16-2</code></td><td>已发布（本地有更新未发）</td><td>走 npm 实发版本</td></tr><tr><td><code>@melt-js/libs-core</code></td><td><code>2026.11.16-2</code></td><td>已发布</td><td>走 npm 实发版本</td></tr><tr><td><code>@melt-js/comps-vue2-ele-vea</code></td><td>不在 dependencies</td><td><strong>未发布（Not found）</strong></td><td>vendor 兜底</td></tr></tbody></table><p>传递依赖 <code>@melt-js/libs-vue2-leva</code> 已在 npm 发布，随对应包解析。</p><h2 id="副本改动清单" tabindex="-1">副本改动清单 <a class="header-anchor" href="#副本改动清单" aria-label="Permalink to &quot;副本改动清单&quot;">​</a></h2><p>副本位于 monorepo 之外，原始仓库保持干净。</p><table tabindex="0"><thead><tr><th>文件 / 目录</th><th>改动</th></tr></thead><tbody><tr><td><code>package.json</code></td><td>三个已发包改为实发版本；移除未发布的 vea 依赖；直接声明 <code>hel-lib-proxy@4.12.3</code></td></tr><tr><td><code>vue.config.js</code></td><td>vea 别名精确匹配到本地 vendor 代理；ele 仍从 <code>node_modules</code> 解析 <code>hel_proxy/entry.js</code>；<code>transpileDependencies</code> 含 <code>@melt-js/libs-core</code></td></tr><tr><td><code>public/vea/hel_dist/</code></td><td>vea 远程产物（meta、js、css、entry、index.html），origin 由 dev 地址改写为 <code>/vea/hel_dist/</code></td></tr><tr><td><code>vendor/vea-proxy/hel_proxy/entry.js</code></td><td>编译期代理入口，<code>exposeLib(&#39;comps-vue2-ele-vea&#39;)</code>，导出 AdminChart、BackToTop、DndList、DragSelect、Kanban、Pagination、RouteTabs、Sticky、UploadExcel、exportJsonToExcel</td></tr><tr><td><code>.env.local</code></td><td>三个远程入口：comps-vue2、ele 走 unpkg 官方源；vea 指向本副本 <code>public/vea</code> 产物</td></tr></tbody></table><h2 id="目录布局" tabindex="-1">目录布局 <a class="header-anchor" href="#目录布局" aria-label="Permalink to &quot;目录布局&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>standalone/&lt;consumer&gt;/</span></span>
<span class="line"><span>├── public/vea/hel_dist/        # 运行期远程产物，随静态站点发布</span></span>
<span class="line"><span>│   ├── hel-meta.json</span></span>
<span class="line"><span>│   ├── index.html</span></span>
<span class="line"><span>│   ├── entry.js</span></span>
<span class="line"><span>│   ├── js/…</span></span>
<span class="line"><span>│   └── css/…</span></span>
<span class="line"><span>├── vendor/vea-proxy/hel_proxy/entry.js   # 编译期代理，打进自己 bundle</span></span>
<span class="line"><span>├── vue.config.js</span></span>
<span class="line"><span>└── .env.local</span></span></code></pre></div><h2 id="关键约束" tabindex="-1">关键约束 <a class="header-anchor" href="#关键约束" aria-label="Permalink to &quot;关键约束&quot;">​</a></h2><ul><li><strong>远程 host 必须是绝对 <code>http(s)://</code> 地址</strong>：<code>libs-core</code> 的 <code>httpUrl</code> 用 <code>new URL(host)</code> 校验，裸 <code>/</code> 相对路径会被拒绝。</li><li><strong>代理与远程产物是两层</strong>：<code>hel_proxy/entry.js</code> 是编译期 webpack 别名目标，随 bundle 编译进去，不放进 <code>public/</code>；<code>hel_dist/</code> 才是运行期浏览器按 URL 加载的静态资源。把代理拷进 <code>public/</code> 会产生一个无人引用、且 <code>hel-lib-proxy</code> 无法按打包规则解析的冗余文件。</li><li><strong>dev origin 会被烤进产物</strong>：<code>hel-meta.json</code> 的 chunk 路径、webpack <code>runtime.*.js</code> 的 publicPath、<code>index.html</code> 三处都可能残留 dev 服务 origin，vendor 拷贝后需批量改写到目标路径，否则懒加载 chunk 仍请求被拒的本地端口。</li></ul><h2 id="验证结果" tabindex="-1">验证结果 <a class="header-anchor" href="#验证结果" aria-label="Permalink to &quot;验证结果&quot;">​</a></h2><ul><li>用官方 registry 在副本目录 <code>pnpm install</code> 通过，不依赖 monorepo 依赖提升。</li><li><code>dev</code> 编译通过（仅 Sass <code>@import</code> 弃用告警），开发端口 <code>50010</code>，预览端口 <code>50020</code>。</li><li>浏览器实测：三个远程库请求 200；登录后进入 <code>/dashboard</code>，菜单与页签正常；vea <code>AdminChart</code> canvas 已挂载；代理具名导出解析成功，无缺导出报错。</li></ul><h2 id="敏感审计结论" tabindex="-1">敏感审计结论 <a class="header-anchor" href="#敏感审计结论" aria-label="Permalink to &quot;敏感审计结论&quot;">​</a></h2><p>推送前扫描源码、env、mock、build、tests、README、<code>public/</code>、<code>vendor/</code>（排除 <code>node_modules/</code>）：</p><ul><li>无 <code>ghp_</code> / <code>npm_</code> 令牌、密钥、私网 IP、内网域名、本地绝对路径；</li><li>无 sourcemap（<code>productionSourceMap: false</code>，产物内无 <code>*.map</code>）；</li><li>外部链接仅为上游公开引用（开源模板作者、公开 CDN、unpkg）；</li><li><code>.env.local</code> 作为本地覆盖文件不入库；<code>node_modules/</code>、<code>dist/</code>、日志、coverage 已排除。</li></ul><h2 id="源码推送与分支策略" tabindex="-1">源码推送与分支策略 <a class="header-anchor" href="#源码推送与分支策略" aria-label="Permalink to &quot;源码推送与分支策略&quot;">​</a></h2><ul><li>源码推送到独立仓库 <code>melt-js/tpl-vue2-admin-ele-vea</code> 的 <code>main</code> 分支。</li><li>远端原有 <code>gh-pages</code> 分支（<code>.nojekyll</code> + <code>dist/</code> 的 Pages 产物）保留不动，源码分支与产物分支分离。</li></ul><h2 id="发包后回归标准链路" tabindex="-1">发包后回归标准链路 <a class="header-anchor" href="#发包后回归标准链路" aria-label="Permalink to &quot;发包后回归标准链路&quot;">​</a></h2><p><code>comps-vue2-ele-vea</code> 发布到 npm 后：</p><ol><li>副本依赖换回 vea 实发版本；</li><li>删除 <code>vendor/vea-proxy/</code>、<code>public/vea/hel_dist/</code> 与 <code>vue.config.js</code> 里的 vea 手写别名；</li><li>代理从 <code>node_modules/@melt-js/comps-vue2-ele-vea/hel_proxy/entry.js</code> 解析；</li><li><code>.env.local</code> 移除本地 vendored host，回到托管地址候选；</li><li>重新跑独立安装、dev 冒烟与生产构建。</li></ol><h2 id="待补与未验证项" tabindex="-1">待补与未验证项 <a class="header-anchor" href="#待补与未验证项" aria-label="Permalink to &quot;待补与未验证项&quot;">​</a></h2><ul><li>副本仅通过 dev 冒烟，<code>build:prod</code> 生产构建未测。</li><li><code>comps-vue2-ele</code> 的 npm 版本落后本地未发版本；发版后需同步副本依赖。</li><li>README 与 <code>.env</code> 仍保留 monorepo <code>pnpm --filter</code>、兄弟包端口等旧措辞，与当前 vendor 现状存在文档漂移，待回归时一并修订。</li><li>运行期远程 host 后续可从 unpkg 切换到自托管 GitHub Pages；只改 <code>VUE_APP_*_HOST</code>，代理入口仍来自 npm 或打进自身 bundle。</li></ul>`,26)])])}const m=d(c,[["render",l]]);export{u as __pageData,m as default};
